<?php

namespace App\Mail;

use App\Models\User;
use App\Support\FrontendUrl;
use Illuminate\Bus\Queueable;
use Illuminate\Mail\Mailable;
use Illuminate\Mail\Mailables\Address;
use Illuminate\Mail\Mailables\Content;
use Illuminate\Mail\Mailables\Envelope;
use Illuminate\Queue\SerializesModels;

/**
 * Password reset link.
 *
 * The token is generated by Laravel's password broker and stored hashed in
 * `password_reset_tokens`; only the plain value is emailed. The link points at
 * the SPA (FRONTEND_URL), not the API — the API has no HTML reset form.
 */
class ResetPasswordMail extends Mailable
{
    use Queueable, SerializesModels;

    public function __construct(
        public User $user,
        public string $token,
        // Resolved while the HTTP request is still available; the mailable
        // itself may be rendered later (if queued) when request() is gone.
        public ?string $frontendBase = null,
    ) {
    }

    public function envelope(): Envelope
    {
        return new Envelope(
            // Explicit sender: the framework default would show the display
            // name from MAIL_FROM_NAME, which is not always set on the server
            // (recipients then see a bare "Laravel").
            from: new Address(config('mail.from.address'), config('acvr.name')),
            subject: 'Reset your ACVR password',
        );
    }

    public function content(): Content
    {
        $base = $this->frontendBase ?: FrontendUrl::base();

        return new Content(
            view: 'emails.reset-password',
            with: [
                'name' => $this->user->name,
                'resetUrl' => $base . '/reset-password?token=' . urlencode($this->token)
                    . '&email=' . urlencode($this->user->email),
                'expiresIn' => (int) config('auth.passwords.users.expire', 60),
            ],
        );
    }
}
